/**
 * In-browser stand-in for the Rust core, for `pnpm dev` in a plain browser and for tests.
 * Data comes from fixtures/demo.json, generated by the real stats engine
 * (`cargo run -p refine-core --example demo_data`). Checks are simulated with a few rules.
 */
import type { Entry } from '../bindings/Entry';
import type { Insights } from '../bindings/Insights';
import type { Mistake } from '../bindings/Mistake';
import type { ModelInfo } from '../bindings/ModelInfo';
import type { ProviderStatus } from '../bindings/ProviderStatus';
import type { Settings } from '../bindings/Settings';
import type { Stats } from '../bindings/Stats';
import type { Tone } from '../bindings/Tone';
import type { Api, Bootstrap } from './api';
import demo from './fixtures/demo.json';
import catalog from './fixtures/categories.json';

const wait = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** A handful of rules, enough to see the result screen in action. */
const RULES: { re: RegExp; fix: string; category: Mistake['category']; pattern: string; why: string; lang: string }[] = [
  { re: /\bmit der (Kunde|Mann)\b/, fix: 'mit dem $1n', category: 'grammar.case', pattern: 'dative after mit', why: "After 'mit' always use the dative.", lang: 'de' },
  { re: /\bmit den (Zug|Kunden?)\b/, fix: 'mit dem $1', category: 'grammar.case', pattern: 'dative after mit', why: "'Mit' takes the dative.", lang: 'de' },
  { re: /\bmachen (wir )?eine Entscheidung\b/, fix: 'treffen $1eine Entscheidung', category: 'lexis.collocation', pattern: 'eine Entscheidung treffen', why: "You 'treffen' a decision in German.", lang: 'de' },
  { re: /\binformations\b/, fix: 'information', category: 'grammar.noun_number', pattern: 'information is uncountable', why: "'Information' has no plural.", lang: 'en' },
  { re: /\bexplain me\b/, fix: 'explain to me', category: 'grammar.preposition', pattern: 'explain to someone', why: "You explain something 'to' someone.", lang: 'en' },
  { re: /\buntil (Monday|Tuesday|Wednesday|Thursday|Friday|tomorrow)\b/, fix: 'by $1', category: 'grammar.preposition', pattern: 'by for deadlines', why: "For deadlines use 'by'.", lang: 'en' },
  { re: /\bYesterday I have (\w+)/, fix: 'Yesterday I $1', category: 'grammar.verb_tense', pattern: 'past simple for finished past', why: "With 'yesterday', use the past simple.", lang: 'en' },
  { re: /\bi\b/, fix: 'I', category: 'orthography.capitalization', pattern: 'capital I', why: "'I' is always a capital letter.", lang: 'en' },
];

type Canned = {
  language: string;
  mistakes: Pick<Mistake, 'original' | 'correction' | 'category' | 'explanation' | 'pattern' | 'impedesMeaning'>[];
  suggestions: Pick<Entry['suggestions'][number], 'kind' | 'original' | 'replacement' | 'explanation'>[];
};

/** Real answers from Qwen3.6-35B-A3B (LM Studio, thinking off), copied verbatim from test runs,
 *  so demos and screenshots show what the model actually returns. */
export const DEMO_TEXTS: Record<string, Canned> = {
  'Dear Mr. Weber, thx for the quick reply. Yesterday I have sent the contract, pls let me know until Friday if everything is fine.': {
    language: 'en',
    mistakes: [
      { original: 'thx for', correction: 'thank you for', category: 'register.formality', pattern: 'formal email abbreviations', impedesMeaning: false, explanation: "Use full words in formal emails. 'Thx' is a chat abbreviation." },
      { original: 'I have sent', correction: 'I sent', category: 'grammar.verb_tense', pattern: 'past simple for finished past', impedesMeaning: false, explanation: "Use the simple past (sent) with specific past times like 'yesterday'." },
      { original: 'pls let', correction: 'please let', category: 'register.formality', pattern: 'formal email abbreviations', impedesMeaning: false, explanation: "Use full words in formal emails. 'Pls' is a chat abbreviation." },
      { original: 'know until Friday', correction: 'know by Friday', category: 'grammar.preposition', pattern: 'by for deadlines', impedesMeaning: true, explanation: "Use 'by' for deadlines (before or on that day). 'Until' means the action continues up to that time." },
    ],
    suggestions: [
      { kind: 'phrase', original: 'if everything is fine', replacement: 'if everything is in order', explanation: 'This is a more professional way to ask for confirmation in business emails.' },
      { kind: 'synonym', original: 'quick reply', replacement: 'prompt response', explanation: 'A common formal collocation for business correspondence.' },
    ],
  },
  'Hallo zusammen, ich habe gestern mit der Kunde gesprochen und er hat gesagt, dass er braucht mehr Zeit für die Tests.': {
    language: 'de',
    mistakes: [
      { original: 'mit der Kunde', correction: 'mit dem Kunden', category: 'grammar.case', pattern: 'dative after mit', impedesMeaning: false, explanation: "The noun 'Kunde' is masculine. After the preposition 'mit', you must use the dative case. The dative form is 'dem Kunden'." },
      { original: 'dass er braucht mehr Zeit', correction: 'dass er mehr Zeit braucht', category: 'grammar.word_order', pattern: 'verb last in subordinate clauses', impedesMeaning: false, explanation: "In a subordinate clause starting with 'dass', the conjugated verb must go to the very end." },
    ],
    suggestions: [
      { kind: 'phrase', original: 'dass er mehr Zeit braucht für die Tests', replacement: 'dass er für die Tests mehr Zeit braucht', explanation: "It is often more natural in German to place the context ('für die Tests') before the time ('mehr Zeit')." },
    ],
  },
};

function cannedCheck(text: string, c: Canned, tone: Tone): Entry {
  let fixed = text;
  const mistakes: Mistake[] = c.mistakes.map((m, i) => {
    const start = text.indexOf(m.original);
    fixed = fixed.replace(m.original, m.correction);
    return {
      ...m,
      id: `m${i + 1}`,
      patternKey: `${c.language}:${m.category}:${m.pattern.replace(/\W+/g, '-')}`,
      span: start >= 0 ? { start, end: start + m.original.length } : null,
    };
  });
  const base = simulateCheck(text, c.language, tone);
  return {
    ...base,
    language: c.language,
    fixedText: fixed,
    mistakes,
    suggestions: c.suggestions.map((s, i) => ({ ...s, id: `s${i + 1}`, span: null })),
    diff: diffFor(text, mistakes),
  };
}

function diffFor(text: string, mistakes: Mistake[]): Entry['diff'] {
  const diff: Entry['diff'] = [];
  let rest = text;
  for (const m of mistakes) {
    const i = rest.indexOf(m.original);
    if (i < 0) continue;
    if (i > 0) diff.push({ op: 'equal', text: rest.slice(0, i) });
    diff.push({ op: 'delete', text: m.original }, { op: 'insert', text: m.correction });
    rest = rest.slice(i + m.original.length);
  }
  if (rest) diff.push({ op: 'equal', text: rest });
  return diff;
}

function simulateCheck(text: string, language: string | null, tone: Tone): Entry {
  const lang = language ?? (/\b(ich|und|nicht|der|die|das|mit)\b/i.test(text) ? 'de' : 'en');
  let fixed = text;
  const mistakes: Mistake[] = [];
  for (const r of RULES.filter((x) => x.lang === lang)) {
    const m = fixed.match(r.re);
    if (!m || m.index === undefined) continue;
    const original = m[0];
    const correction = original.replace(r.re, r.fix);
    const start = text.indexOf(original);
    fixed = fixed.replace(original, correction);
    mistakes.push({
      id: `m${mistakes.length + 1}`,
      original,
      correction,
      category: r.category,
      impedesMeaning: false,
      explanation: r.why,
      pattern: r.pattern,
      patternKey: `${lang}:${r.category}:${r.pattern.replace(/\W+/g, '-')}`,
      span: start >= 0 ? { start, end: start + original.length } : null,
    });
  }
  const diff: Entry['diff'] = [];
  let rest = text;
  for (const m of mistakes) {
    const i = rest.indexOf(m.original);
    if (i < 0) continue;
    if (i > 0) diff.push({ op: 'equal', text: rest.slice(0, i) });
    diff.push({ op: 'delete', text: m.original }, { op: 'insert', text: m.correction });
    rest = rest.slice(i + m.original.length);
  }
  if (rest) diff.push({ op: 'equal', text: rest });
  const words = text.split(/\s+/).filter(Boolean).length;
  return {
    schemaVersion: 1,
    id: crypto.randomUUID(),
    createdAt: new Date().toISOString(),
    input: text,
    language: lang,
    tone: { id: tone.id, name: tone.name },
    model: { providerId: 'openrouter', providerKind: 'openRouter', model: 'mock/model' },
    fixedText: fixed,
    mistakes,
    suggestions:
      words > 6
        ? [
            {
              id: 's1',
              kind: 'synonym',
              original: fixed.split(/\s+/).slice(0, 2).join(' '),
              replacement: lang === 'de' ? 'Kurz gesagt' : 'In short',
              explanation: 'A smoother way to open (sample suggestion from the mock).',
              span: null,
            },
          ]
        : [],
    watch: [],
    diff,
    wordCount: words,
    durationMs: 1200,
    warnings: [],
  };
}

const MODELS: ModelInfo[] = [
  { id: 'anthropic/claude-sonnet-4.5', name: 'Anthropic: Claude Sonnet 4.5', contextLength: 1000000, promptPrice: 3, completionPrice: 15, structuredOutputs: true },
  { id: 'openai/gpt-5-mini', name: 'OpenAI: GPT-5 Mini', contextLength: 400000, promptPrice: 0.25, completionPrice: 2, structuredOutputs: true },
  { id: 'google/gemini-2.5-flash', name: 'Google: Gemini 2.5 Flash', contextLength: 1048576, promptPrice: 0.3, completionPrice: 2.5, structuredOutputs: true },
  { id: 'meta-llama/llama-3.3-70b-instruct', name: 'Meta: Llama 3.3 70B Instruct', contextLength: 131072, promptPrice: 0.13, completionPrice: 0.4, structuredOutputs: false },
];

export function createMockApi(): Api {
  let settings = structuredClone(demo.settings) as Settings;
  let tones = structuredClone(demo.tones) as Tone[];
  const entries = (structuredClone(demo.entries) as Entry[]).reverse(); // newest first
  const stats = demo.stats as unknown as Stats;
  let insights: Insights | null = demo.insights as unknown as Insights;
  let providers: ProviderStatus[] = settings.providers.map((p) => ({ id: p.id, hasKey: p.id === 'openrouter' }));
  if (!settings.providers[0]!.model) settings.providers[0]!.model = 'anthropic/claude-sonnet-4.5';

  return {
    async bootstrap(): Promise<Bootstrap> {
      return { appVersion: '0.1.0', platform: 'web', settings, tones, providers, categories: catalog as Bootstrap['categories'] };
    },
    async saveSettings(next) {
      settings = next;
      return settings;
    },
    async setApiKey(providerId, key) {
      providers = providers.map((p) => (p.id === providerId ? { ...p, hasKey: !!key } : p));
      return providers;
    },
    async listModels() {
      await wait(400);
      return MODELS;
    },
    async saveTone(tone) {
      const saved = tone.id ? tone : { ...tone, id: `custom-${Date.now()}` };
      tones = tones.some((t) => t.id === saved.id) ? tones.map((t) => (t.id === saved.id ? saved : t)) : [...tones, saved];
      return saved;
    },
    async deleteTone(id) {
      tones = tones.filter((t) => t.id !== id);
      return tones;
    },
    async checkText(req) {
      await wait(1400);
      const tone = tones.find((t) => t.id === req.toneId) ?? tones[0]!;
      const canned = DEMO_TEXTS[req.text.trim()];
      const entry = canned ? cannedCheck(req.text.trim(), canned, tone) : simulateCheck(req.text, req.language ?? null, tone);
      entries.unshift(entry);
      return entry;
    },
    async history({ before, limit = 40, query }) {
      const q = query?.toLowerCase();
      const list = entries.filter(
        (e) => (!before || e.createdAt < before) && (!q || `${e.input}\n${e.fixedText}`.toLowerCase().includes(q)),
      );
      const page = list.slice(0, limit);
      return { entries: page, nextBefore: list.length > limit ? page[page.length - 1]!.createdAt : null };
    },
    async getEntry(id) {
      const e = entries.find((x) => x.id === id);
      if (!e) throw { kind: 'notFound', message: 'Not found: entry' };
      return e;
    },
    async deleteEntry(id) {
      const i = entries.findIndex((e) => e.id === id);
      if (i >= 0) entries.splice(i, 1);
    },
    async getStats() {
      return stats;
    },
    async getInsights() {
      return insights;
    },
    async refreshInsights() {
      await wait(1500);
      insights = { ...(insights as Insights), generatedAt: new Date().toISOString() };
      return insights;
    },
    async setPatternPref(key, pinned) {
      for (const l of stats.languages) {
        for (const p of l.patterns) {
          if (p.key !== key) continue;
          p.pinned = pinned === true;
          p.dismissed = pinned === false;
          p.onWatchList = pinned === true || (pinned === null && l.watchList.includes(key));
        }
      }
      return structuredClone(stats);
    },
    async recordReview() {
      return stats;
    },
    async exportHistory() {
      await wait(300);
      return '/Users/you/Downloads/refine-export-demo.json';
    },
    async revealPath() {},
    async touch() {},
    onEvent() {
      return () => {};
    },
  };
}
